public static String toString(final char ch) {
    // Cache for ASCII characters (0-127)
    // Lazily initialized on first use
    if (ch < 128) {
        // Use a static array for cache
        if (AsciiStringCache.cache[ch] == null) {
            synchronized (AsciiStringCache.cache) {
                if (AsciiStringCache.cache[ch] == null) {
                    AsciiStringCache.cache[ch] = new String(new char[]{ ch });
                }
            }
        }
        return AsciiStringCache.cache[ch];
    }
    // Non-ASCII characters are not cached
    return new String(new char[]{ ch });
}

