    // If the source list is empty there's nothing to move
    if (list.size == 0) {
        return;
    }
    // If this list is empty we can simply transplant the nodes
    if (this.size == 0) {
        this.firstNode = list.firstNode;
        this.lastNode = list.lastNode;
    } else {
        // Link the end of this list with the beginning of the source list
        this.lastNode.next = list.firstNode;
        list.firstNode.prev = this.lastNode;
        this.lastNode = list.lastNode;
    }
    // Update size
    this.size += list.size;
    // Clear the source list
    list.firstNode = null;
    list.lastNode = null;
    list.size = 0;
}

