private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop must not be null");
    }
    OuterFaceCirculator cir = new OuterFaceCirculator(start, dir);
    Node cur = cir.current(); // current node of the circulator
    while (true) {
        if (predicate.test(cur)) {
            return cir;
        }
        if (cur.equals(stop)) {
            return cir;
        }
        if (dir > 0) {
            cir.next();
        } else {
            cir.prev();
        }
        cur = cir.current();
        // guard against unexpected nulls or endless loop
        if (cur == null || cur.equals(start)) {
            break;
        }
    }
    // if nothing matched, return cir that points to the stop node
    return new OuterFaceCirculator(stop, dir);
}

