protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null){
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()){
        return null; // empty tour
    }
    // Map from vertex to adjacent edges for quick traversal
    Map<V, List<E>> adj = new HashMap<>();
    for (E e : tour){
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adj.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adj.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }
    // Begin traversal from an arbitrary edge
    Iterator<E> it = tour.iterator();
    E startEdge = it.next();
    V current = graph.getEdgeSource(startEdge);
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);
    remaining.remove(startEdge);
    vertices.add(current);
    edges.add(startEdge);
    V next = graph.getEdgeTarget(startEdge);
    vertices.add(next);
    current = next;
    // Traverse until all edges are used
    while (!remaining.isEmpty()){
        boolean found = false;
        List<E> adjEdges = adj.getOrDefault(current, Collections.emptyList());
        for (E e : adjEdges){
            if (!remaining.contains(e)){
                continue;
            }
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current)){
                edges.add(e);
                vertices.add(tgt);
                current = tgt;
                found = true;
                break;
            } else if (tgt.equals(current)){
                edges.add(e);
                vertices.add(src);
                current = src;
                found = true;
                break;
            }
        }
        if (!found){
            // no connecting edge found, break
            break;
        }
        remaining.remove(edges.get(edges.size() - 1));
    }
    // If we did not traverse all edges, the set does not form a simple tour
    if (!remaining.isEmpty()){
        return null;
    }
    // Total weight of the tour
    double totalWeight = 0.0;
    for (E e : edges){
        totalWeight += graph.getEdgeWeight(e);
    }
    return new GraphPathImpl<V,E>(graph, vertices, edges, totalWeight);
}

