private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if(bounds == null){
        throw new IllegalArgumentException("Bounds list cannot be null");
    }
    int size = bounds.size();
    List<Integer> suffix = new ArrayList<>(size);
    long total = 0L;
    // compute total sum first
    for(Integer val : bounds){
        if(val != null){
            total += val.longValue();
        }
    }
    long runningSum = 0L;
    // compute suffix sums from end to start
    for(int i=size-1; i>=0; i--){
        Integer val = bounds.get(i);
        if(val != null){
            runningSum += val.longValue();
        }
        // cast to int, may overflow but matches List<Integer> signature
        suffix.add(0, runningSum > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int)runningSum);
    }
    return new Pair<>(suffix, total);
}

