private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    // Make a sorted copy of keys (natural order)
    List<K> sorted = new ArrayList<>(keys);
    sorted.sort(null); // requires K to be Comparable

    for (K key : keys) {
        if (key == null) {
            lowerBounds.add(-1);
            continue;
        }
        int idx = Collections.binarySearch(sorted, key);
        int lb;
        if (idx < 0) {
            // key not found; insertion point is -idx - 1
            lb = (-idx - 1) - 1;
        } else {
            // key found; look for previous element
            lb = idx - 1;
        }
        lowerBounds.add(lb >= 0 ? lb : -1);
    }
    return lowerBounds;
}

