    List<Integer> upperBounds = new ArrayList<>();
    for (K key : keys) {
        if (key == null) {
            upperBounds.add(null);
            continue;
        }
        try {
            int bound;
            if (key instanceof Number) {
                // Use numeric value plus a small offset as an arbitrary upper bound
                bound = ((Number) key).intValue() + 1;
            } else {
                // Fallback: use hash code magnitude as a proxy for an upper bound
                bound = Math.abs(key.hashCode());
            }
            upperBounds.add(bound);
        } catch (Exception e) {
            // In case any unexpected exception occurs, record zero as a safe lower bound
            upperBounds.add(0);
        }
    }
    return upperBounds;
}

