@SuppressWarnings("unchecked")
public static void addToClassPath(Vector<URL> cpV, String dir) {
    if (cpV == null || dir == null) {
        throw new IllegalArgumentException("classpath vector and directory must not be null");
    }
    File directory = new File(dir);
    if (!directory.exists() || !directory.isDirectory()) {
        throw new IllegalArgumentException("Provided path is not a directory: " + dir);
    }
    File[] files = directory.listFiles();
    if (files == null) {
        return; // empty or inaccessible directory
    }
    for (File file : files) {
        if (file.isFile() && file.getName().toLowerCase().endsWith(".jar")) {
            try {
                URL jarUrl = file.toURI().toURL();
                cpV.add(jarUrl);
            } catch (MalformedURLException e) {
                // Skip files that cannot be converted to a URL
                System.err.println("Skipping invalid jar URL: " + file.getAbsolutePath());
            }
        }
    }
}

