public static String applyRelativePath(String path,String relativePath){
    if (path == null || relativePath == null){
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    boolean isAbsolute = path.startsWith("/");
    String[] baseParts = path.split("/");
    String[] relParts = relativePath.split("/");
    java.util.ArrayList<String> stack = new java.util.ArrayList<>();
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        result.append(stack.get(i));
        if (i < stack.size() - 1) {
            result.append("/");
        }
    }
    // Ensure at least '/' if result is empty
    if (result.length() == 0) {
        result.append("/");
    }
    return result.toString();
}

