protected int removeUnusedNodes(){
    int removed = 0;
    try {
        // If the root itself is inactive, remove the entire tree
        if (root == null) {
            return removed;
        }
        if (!root.isActive()) {
            java.util.Queue<Category> q = new java.util.LinkedList<>();
            q.add(root);
            while (!q.isEmpty()) {
                Category cur = q.poll();
                removed++;
                java.util.List<Category> ch = cur.getChildren();
                if (ch != null) {
                    q.addAll(ch);
                }
            }
            root = null;
            return removed;
        }

        // Use a stack to traverse the tree iteratively
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category parent = stack.pop();
            java.util.List<Category> children = parent.getChildren();
            if (children == null) continue;
            for (int i = children.size() - 1; i >= 0; i--) {
                Category child = children.get(i);
                if (!child.isActive()) {
                    // Count all nodes in the subtree rooted at child
                    java.util.Queue<Category> q = new java.util.LinkedList<>();
                    q.add(child);
                    while (!q.isEmpty()) {
                        Category cur = q.poll();
                        removed++;
                        java.util.List<Category> ch = cur.getChildren();
                        if (ch != null) {
                            q.addAll(ch);
                        }
                    }
                    // Remove the inactive child
                    children.remove(i);
                } else {
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
    return removed;
}

