public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null) {
        return;
    }
    // Assume the class has a field named 'name' containing the full name string.
    String fullName = this.name; // or use getName() if available
    if (fullName == null) {
        return;
    }
    int start = nameStart;
    if (start < 0) {
        start = 0;
    }
    if (start > fullName.length()) {
        return;
    }
    String sub = fullName.substring(start);
    // Split by whitespace to find individual words
    String[] parts = sub.split("\\s+");
    for (String part : parts) {
        if (!part.isEmpty()) {
            buf.append(part.charAt(0));
        }
    }
}

