    // Validate input parameters
    if (file == null) {
        throw new IllegalArgumentException("File argument must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("File does not exist or is not a regular file: " + file);
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        // No time ranges provided, return an empty list
        return Collections.emptyList();
    }

    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Basic safety: skip empty or whitespace-only lines
            if (line.trim().isEmpty()) {
                continue;
            }
            try {
                // Assuming ThreadSnapshot has a static parser that accepts a line of text
                ThreadSnapshot snapshot = ThreadSnapshot.parseFromLine(line);

                // Validate snapshot parsing
                if (snapshot == null) {
                    continue;
                }

                long snapshotTime = snapshot.getTimestamp(); // Assume this method exists

                boolean inRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range == null) {
                        continue;
                    }
                    long start = range.getStartTime(); // Assume getters exist
                    long end   = range.getEndTime();
                    if (start <= snapshotTime && snapshotTime <= end) {
                        inRange = true;
                        break;
