private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }
    int count = 0;
    try {
        if (descriptor.charAt(0) == '(') {
            int i = 1;
            while (true) {
                if (i >= descriptor.length()) {
                    throw new IllegalArgumentException("Malformed descriptor: missing ')'");
                }
                char c = descriptor.charAt(i);
                if (c == ')') {
                    break;
                }
                // Skip array type indicators
                while (c == '[') {
                    i++;
                    if (i >= descriptor.length()) {
                        throw new IllegalArgumentException("Malformed descriptor in array type");
                    }
                    c = descriptor.charAt(i);
                }
                if (c == 'L') {
                    i++; // skip 'L'
                    while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    if (i >= descriptor.length()) {
                        throw new IllegalArgumentException("Malformed descriptor: missing ';' for object type");
                    }
                    i++; // skip ';'
                } else {
                    // Primitive type consumes one character
                    i++;
                }
                count++;
            }
        } else {
            // Single type descriptor
            count = 1;
        }

        for (int k = 0; k < count; k++) {
            if (pos <= 0) {
                throw new IllegalStateException("Frame stack underflow during pop");
            }
            pos--;
        }
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }
}

